ids = await orders_list_order_ids()
futures = [orders_get_order(order_id=str(i)) for i in ids]
orders = [await f for f in futures]
cents = {}
bad = []
for o in orders:
    try:
        c = round(float(o["amount"]) * 100)
        cents[o["region"]] = cents.get(o["region"], 0) + c
    except Exception as e:
        bad.append({"order_id": o.get("order_id"), "err": str(e)})
totals = {r: "%d.%02d" % (c // 100, c % 100) for r, c in sorted(cents.items())}
return {
    "n_ids": len(ids),
    "n_unique_ids": len(set(map(str, ids))),
    "n_orders": len(orders),
    "n_bad": len(bad),
    "bad_sample": bad[:5],
    "totals": totals,
    "sample_order": orders[0] if orders else None,
}

